std::wstring Quote(std::wstring_view v){std::wstring s=L"\"";size_t n=0;for(auto c:v){if(c==L'\\'){++n;continue;}s.append(n*(c==L'"'?2:1),L'\\');n=0;if(c==L'"')s+=L'\\';s+=c;}s.append(n*2,L'\\');return s+L'"';}
struct H{HANDLE h=nullptr;~H(){if(h&&h!=INVALID_HANDLE_VALUE)CloseHandle(h);}};
