    SECURITY_ATTRIBUTES sa{sizeof(sa),nullptr,TRUE};H out,err,input;out.h=CreateFileW((std::wstring(argv[1])+L".stdout").c_str(),GENERIC_WRITE,FILE_SHARE_READ,&sa,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr);err.h=CreateFileW((std::wstring(argv[1])+L".stderr").c_str(),GENERIC_WRITE,FILE_SHARE_READ,&sa,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr);input.h=CreateFileW(L"NUL",GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,&sa,OPEN_EXISTING,0,nullptr);if(out.h==INVALID_HANDLE_VALUE||err.h==INVALID_HANDLE_VALUE||input.h==INVALID_HANDLE_VALUE)return 93;
    SIZE_T size=0;InitializeProcThreadAttributeList(nullptr,1,0,&size);std::vector<unsigned char> storage(size);auto attributes=reinterpret_cast<LPPROC_THREAD_ATTRIBUTE_LIST>(storage.data());if(!InitializeProcThreadAttributeList(attributes,1,0,&size))return 94;HANDLE handles[]{out.h,err.h,input.h};if(!UpdateProcThreadAttribute(attributes,0,PROC_THREAD_ATTRIBUTE_HANDLE_LIST,handles,sizeof(handles),nullptr,nullptr))return 95;
    STARTUPINFOEXW si{};si.StartupInfo.cb=sizeof(si);si.StartupInfo.dwFlags=STARTF_USESTDHANDLES;si.StartupInfo.hStdInput=input.h;si.StartupInfo.hStdOutput=out.h;si.StartupInfo.hStdError=err.h;si.lpAttributeList=attributes;std::wstring cmd;for(int i=4;i<argc;++i){if(!cmd.empty())cmd+=L' ';cmd+=Quote(argv[i]);}PROCESS_INFORMATION pi{};BOOL created=CreateProcessW(argv[4],cmd.data(),nullptr,nullptr,TRUE,CREATE_SUSPENDED|CREATE_NO_WINDOW|EXTENDED_STARTUPINFO_PRESENT,nullptr,argv[3],&si.StartupInfo,&pi);DeleteProcThreadAttributeList(attributes);if(!created){std::wcerr<<L"CreateProcess error "<<GetLastError();return 96;}H process,thread;process.h=pi.hProcess;thread.h=pi.hThread;if(!AssignProcessToJobObject(job.h,process.h)){TerminateProcess(process.h,97);return 97;}if(ResumeThread(thread.h)==static_cast<DWORD>(-1)){TerminateJobObject(job.h,98);return 98;}if(WaitForSingleObject(process.h,static_cast<DWORD>(std::stoul(argv[2])))!=WAIT_OBJECT_0){TerminateJobObject(job.h,99);WaitForSingleObject(process.h,2000);return 99;}DWORD exit=100;GetExitCodeProcess(process.h,&exit);return static_cast<int>(exit);
